/*
 * Index of the bin holding x: the count of cut points <= x, plus one for the
 * leading missing bin. Matches numpy searchsorted(side="right") + 1.
 */
static int bin_index(const float *cuts, int n_cuts, float x)
{
    int lo = 0, hi = n_cuts;

    if (isnan(x))
        return 0; /* missing bin */

    while (lo < hi)
    {
        int mid = lo + ((hi - lo) >> 1);
        if (x < cuts[mid])
            hi = mid;
        else
            lo = mid + 1;
    }
    return lo + 1;
}

void har_ebm_predict(const float features[HAR_N_FEATURES],
                     float scores[HAR_N_CLASSES])
{
    int t, c;

    for (c = 0; c < HAR_N_CLASSES; ++c)
        scores[c] = har_intercept[c];

    for (t = 0; t < HAR_N_TERMS; ++t)
    {
        const float *cuts = &har_cuts[har_cut_off[t]];
        int n_cuts = (int)(har_cut_off[t + 1] - har_cut_off[t]);
        int bin = bin_index(cuts, n_cuts, features[har_term_feature[t]]);
        const float *row = &har_scores[har_score_off[t] + bin * HAR_N_CLASSES];

        for (c = 0; c < HAR_N_CLASSES; ++c)
            scores[c] += row[c];
    }
}
